    // Fonction de normalisation pour la comparaison fuzzy
const normalizeString = (str) => {
  if (!str || typeof str !== 'string') return ''
  return str
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '') // retire les accents
    .trim()
}

    // Vérifier les doublons
